import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], fw['framework'])
                pkgs[key] = pkg['resolvedVersion']
        result[name] = pkgs
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []

all_projects = sorted(set(list(b.keys()) + list(a.keys())))
for proj in all_projects:
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    all_keys = sorted(set(list(bp.keys()) + list(ap.keys())))
    for key in all_keys:
        pkg_id, fw = key
        bv = bp.get(key)
        av = ap.get(key)
        if bv and av and bv == av:
            unchanged.append((proj, pkg_id, fw, bv))
        elif bv and av and bv != av:
            changes.append((proj, pkg_id, fw, bv, av, 'Aligned to highest version'))
        elif bv and not av:
            changes.append((proj, pkg_id, fw, bv, '-', 'Removed'))
        elif not bv and av:
            changes.append((proj, pkg_id, fw, '-', av, 'Added'))

print('=== CHANGES ===')
for c in changes:
    print(f'  {c[0]:20s} | {c[1]:45s} | {c[2]:8s} | {c[3]:10s} -> {c[4]:10s} | {c[5]}')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]:20s} | {u[1]:45s} | {u[2]:8s} | {u[3]}')
